import{z as l,x as i,o as e,c as s,q as t,j as n,D as a,d as A,s as B,S as o}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"checkpoint 的挑选","description":"","frontmatter":{"title":"checkpoint 的挑选","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/pf2-checkpoint-selection.md","filePath":"llm/pf2-checkpoint-selection.md","lastUpdated":1791063341000}'),p={name:"llm/pf2-checkpoint-selection.md"};function c(h,E,C,d,m,F){const r=i("Mermaid");return e(),s("div",null,[E[2]||(E[2]=t('<h1 id="checkpoint-的挑选" tabindex="-1">checkpoint 的挑选 <a class="header-anchor" href="#checkpoint-的挑选" aria-label="Permalink to &quot;checkpoint 的挑选&quot;">​</a></h1><div class="epigraph"><p>选点是一次有判据的决策，不是浏览相册：每个被送出去的候选，都要能说出它凭什么排在别人前面。</p><footer>—— 据 OLMo 2 多数据序 souping（arXiv:2501.00656）与 Wortsman et al., ICML 2022 的模型汤实践整理</footer></div><p><a href="/llm/pf2-annealing-curriculum">上一课</a>的退火段在检查点分线上留下了一批候选：主干终点、退火途中各点、多数据顺序的多路产物。本课写从中挑出交付物的流程：候选池怎么构、判据用什么、平均与单点的取舍、以及怎么防止把选点做成对评测集的过拟合。<a href="/llm/ti-checkpoint-engineering">检查点的存储与分线</a>已提供设施；本课用的是配方口径。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>选点容易滑成两种坏形态。一种是<strong>默认终点</strong>：训练到死线，拿最后一个检查点交付，不问倒数第二个或退火中途是否更好——日程的尾部与数据课程的存在意味着终点未必是局部最优的交付点。另一种是<strong>榜单挑选</strong>：把所有候选跑一遍公开榜，谁高分选谁——这在统计上是对评测集的选择性使用，选出的「最好」有一部分是评测集上的运气，换一批题就蒸发。两种形态的共同病根是：没有先于观测的选点判据。</p><p><span class="marginnote">「预注册」就是先把判据写死、再开始看数据——好比考试前公布评分标准，而不是看完答卷再定标准。不预注册的话，人总能给自己偏好的候选找一条有利的理由，判据就形同虚设。</span></p><h3 id="候选池与判据" tabindex="-1">候选池与判据 <a class="header-anchor" href="#候选池与判据" aria-label="Permalink to &quot;候选池与判据&quot;">​</a></h3><p>候选池先分类，再逐类定判据。<strong>主干与退火各点</strong>：按训练 CE 与探针分数的联合表现入围，要求轨迹契约完好——没有尖峰回退污染的脚注。<strong>多路退火产物</strong>：共享预训练起点、只差数据顺序，先各自评，再考察<a href="/llm/model-soups-averaging">均匀汤与贪心汤</a>：均匀平均全部成员，或用验证集拒掉偏离远的成员再平均；汤的推理成本与单体相同，是便宜的提升。<strong>EMA 权重</strong>：时间轴上的隐式平均，作为另一类候选与汤并列。判据权重启动前写进<a href="/llm/pf2-pretrain-checklist">检查清单</a>：哪张留出集说了算、平手怎么办、汤与单点差多少以内算平手。</p>',8)),(e(),n(o,null,{default:a(()=>[B(r,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20C%5B%22%E5%80%99%E9%80%89%E6%B1%A0%EF%BC%9A%E4%B8%BB%E5%B9%B2%E7%82%B9%20%2F%20%E9%80%80%E7%81%AB%E7%82%B9%20%2F%20%E5%A4%9A%E8%B7%AF%E4%BA%A7%E7%89%A9%20%2F%20EMA%22%5D%20--%3E%20S%7B%22%E9%80%90%E7%B1%BB%E8%AF%84%E4%BC%B0%EF%BC%9A%E7%95%99%E5%87%BA%E9%9B%86%20%2B%20%E6%8E%A2%E9%92%88%22%7D%0A%20%20S%20--%3E%20SO%7B%22%E5%A4%9A%E8%B7%AF%E6%88%90%E5%91%98%EF%BC%9A%E5%B9%B3%E5%9D%87%E8%BF%98%E6%98%AF%E5%8D%95%E7%82%B9%EF%BC%9F%22%7D%0A%20%20SO%20--%3E%7C%E6%88%90%E5%91%98%E9%9D%A0%E8%BF%91%7C%20U%5B%22%E5%9D%87%E5%8C%80%E6%B1%A4%22%5D%0A%20%20SO%20--%3E%7C%E6%9C%89%E8%BF%9C%E7%82%B9%7C%20G%5B%22%E8%B4%AA%E5%BF%83%E6%B1%A4%EF%BC%9A%E9%AA%8C%E8%AF%81%E9%9B%86%E6%8B%92%E8%BF%9C%E7%82%B9%22%5D%0A%20%20SO%20--%3E%7C%E5%88%86%E6%95%A3%E4%B8%94%E5%B0%91%E6%95%B0%E7%AA%81%E5%87%BA%7C%20P%5B%22%E5%8F%96%E6%9C%80%E4%BC%98%E5%8D%95%E7%82%B9%22%5D%0A%20%20U%20--%3E%20F%5B%22%E6%8C%89%E9%A2%84%E6%B3%A8%E5%86%8C%E5%88%A4%E6%8D%AE%E9%80%89%E5%87%BA%E4%BA%A4%E4%BB%98%E7%89%A9%22%5D%0A%20%20G%20--%3E%20F%0A%20%20P%20--%3E%20F%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[A(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=t('<h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>执行三条。第一，<strong>留出集分层</strong>：选点用的留出集与发布评测用的门禁集分开；前者可以频繁用，后者只在选点结束后动用一次。第二，<strong>平手与方差</strong>：候选间差距小于种子方差时不宣布胜负，宁可交付多候选给后训练接口并行试；种子数按实测方差反推，见<a href="/llm/ti-hparam-search-eng">超参搜索</a>的噪声下界口径。第三，<strong>谱系写全</strong>：交付物附带它的来源——哪个 run、哪个检查点、是否汤、成员列表与拒绝记录；这继承配方管理一课的四元组纪律。</p><p><span class="marginnote">同一条训练轨迹上相邻检查点的平均是时间轴平滑，与「超参轴的汤」不是一回事：前者只压噪声，后者需要真正的多样性；把同轨迹多点平均冒充模型汤，会在对比实验里高出一段不存在的收益。</span></p><p><span class="marginnote">数字实例：假如两个候选在留出集上 CE 只差 0.002，但同一个候选只换随机种子重训一遍，CE 本身就能波动 ±0.005——那这 0.002 的「胜负」纯属噪声，不该宣布；差距明显大于种子波动才有意义。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>为什么平均能赢单点：多路退火的成员在不同数据顺序上学到略有不同的解，平均落在它们张成空间的中心，抹掉各自的特异性误差；Wortsman 等的结果表明共享预训练上的多样微调平均后普遍不差于最优成员。但它有两个前提——成员足够靠近（权重空间里可加），以及验证集能识别远点；两个前提都不满足时，汤会夹生，最优单点反而是安全交付。为什么判据要预注册：选点是一次自由度很高的搜索，评测集被反复使用后，最高分不再是能力的无偏估计；预注册把这次搜索的预算与停止规则定死，评测集的统计效力留给最终门禁。</p><p><span class="marginnote">直觉类比：几个水平相当的考生各在不同题型上丢过冤枉分，把他们的解法取平均，各自的偏科误差互相抵消，整体反而稳过任何单人——前提是他们的思路确实相近，一个走文一个走理的答案平均起来只会夹生。</span></p>',7)),(e(),n(o,null,{default:a(()=>[B(r,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20LR%0A%20%20A%5B%22%E5%80%99%E9%80%89%E6%B1%A0%208%20%E4%B8%AA%E6%A3%80%E6%9F%A5%E7%82%B9%22%5D%20--%3E%20B%5B%22%E5%90%8C%E4%B8%80%E5%BC%A0%E9%80%89%E7%82%B9%E9%9B%86%E5%8F%8D%E5%A4%8D%E6%89%93%E5%88%86%22%5D%0A%20%20B%20--%3E%20C%5B%22%E6%AF%8F%E4%B8%AA%E5%88%86%E6%95%B0%20%3D%20%E7%9C%9F%E5%AE%9E%E8%83%BD%E5%8A%9B%20%2B%20%E8%BF%90%E6%B0%94%E6%B3%A2%E5%8A%A8%22%5D%0A%20%20C%20--%3E%20D%5B%22%E6%8C%91%E6%9C%80%E9%AB%98%E5%88%86%EF%BC%9A%E8%BF%90%E6%B0%94%E4%B9%9F%E8%A2%AB%E5%A5%96%E5%8A%B1%22%5D%0A%20%20D%20--%3E%20E%7B%22%E6%8D%A2%E4%B8%80%E5%BC%A0%E6%B2%A1%E8%A7%81%E8%BF%87%E7%9A%84%E9%A2%98%E5%86%8D%E6%B5%8B%22%7D%0A%20%20E%20--%3E%7C%E5%90%8D%E6%AC%A1%E5%A4%A7%E6%B4%97%E7%89%8C%7C%20F%5B%22%E9%80%89%E7%82%B9%E9%9B%86%E8%A2%AB%E7%94%A8%E5%BA%9F%EF%BC%9A%E9%AB%98%E5%88%86%E6%98%AF%E8%BF%87%E6%8B%9F%E5%90%88%22%5D%0A%20%20E%20--%3E%7C%E5%90%8D%E6%AC%A1%E5%9F%BA%E6%9C%AC%E4%B8%8D%E5%8F%98%7C%20G%5B%22%E9%80%89%E6%8B%A9%E5%8F%AF%E4%BF%A1%EF%BC%9A%E5%8F%AF%E4%BA%A4%E4%BB%98%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[A(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=t('<p>这一张图回答的是榜单挑选为什么会失真：候选越多、选点集被刷的次数越多，冠军分数里掺的运气成分越大，换题后名次洗牌就是信号。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课选的是预训练交付物，不含后训练之后的最终选型；RL 或蒸馏阶段的候选语义不同。汤的成员资格以「共享预训练起点」为界，不同词表、过远策略的两支不在范围内，见<a href="/llm/model-soups-averaging">模型汤</a>的边界课。检查点怎么存、分线怎么保留、resume 演练怎么做，是<a href="/llm/ti-checkpoint-engineering">检查点工程</a>与<a href="/llm/pretrain-ckpt">预训练检查点</a>的口径，本课只消费分线产物。发布前的全面评估是下一课的模型评估门禁——选点只回答「送谁去考」，门禁才回答「能不能发布」。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>选点是预注册判据下的决策：候选池分类，判据启动前写进清单。</li><li>多路退火产物先评单点再评汤：均匀汤、贪心汤与最优单点三选一，平手并行交付。</li><li>选点留出集与发布门禁集分开；差距小于种子方差不宣布胜负。</li><li>交付物带全谱系：来源 run、检查点、汤成员与拒绝记录。</li><li>出处：Wortsman et al., Model Soups, ICML 2022；OLMo 2（arXiv:2501.00656）的多数据序实践。</li></ul>',5))])}const g=l(p,[["render",c]]);export{f as __pageData,g as default};
